import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
class SimpleAuthScreen extends StatefulWidget{const SimpleAuthScreen({super.key});@override State<SimpleAuthScreen> createState()=>_SimpleAuthScreenState();}
class _SimpleAuthScreenState extends State<SimpleAuthScreen>{final email=TextEditingController(),password=TextEditingController(),name=TextEditingController();bool register=false,busy=false;String role='student';Future<void> submit()async{if(email.text.trim().isEmpty||password.text.length<6)return;setState(()=>busy=true);try{if(register){final c=await FirebaseAuth.instance.createUserWithEmailAndPassword(email:email.text.trim(),password:password.text);await FirebaseFirestore.instance.collection('users').doc(c.user!.uid).set({'fullName':name.text.trim(),'email':email.text.trim(),'accountType':role,'isVerified':role=='student','createdAt':FieldValue.serverTimestamp()});if(role=='student')await FirebaseFirestore.instance.collection('students').doc(c.user!.uid).set({'fullName':name.text.trim(),'gpa':0,'skills':[],'interests':[],'favoriteSubjects':[],'abilities':[],'createdAt':FieldValue.serverTimestamp()});else await FirebaseFirestore.instance.collection('advisors').doc(c.user!.uid).set({'fullName':name.text.trim(),'isVerified':false,'verificationStatus':'pending','createdAt':FieldValue.serverTimestamp()});}else{await FirebaseAuth.instance.signInWithEmailAndPassword(email:email.text.trim(),password:password.text);}}on FirebaseAuthException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message??'تعذر إتمام العملية.')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:Column(children:[const Icon(Icons.school_rounded,size:72),const SizedBox(height:12),Text(register?'إنشاء حساب':'تسجيل الدخول',style:Theme.of(context).textTheme.headlineSmall),if(register)...[const SizedBox(height:16),TextField(controller:name,decoration:const InputDecoration(labelText:'الاسم الكامل')),DropdownButtonFormField(value:role,items:const[DropdownMenuItem(value:'student',child:Text('طالب')),DropdownMenuItem(value:'advisor',child:Text('مستشار تعليمي'))],onChanged:(v)=>setState(()=>role=v!))],const SizedBox(height:12),TextField(controller:email,decoration:const InputDecoration(labelText:'البريد الإلكتروني')),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'كلمة المرور (6 أحرف على الأقل)')),const SizedBox(height:20),FilledButton(onPressed:busy?null:submit,child:Text(busy?'جارٍ التنفيذ...':register?'إنشاء الحساب':'دخول')),TextButton(onPressed:()=>setState(()=>register=!register),child:Text(register?'لديك حساب؟ سجّل الدخول':'مستخدم جديد؟ أنشئ حسابًا'))])))));}
